FROM penguins |> WHERE body_mass_g IS NOT NULL |> EXTEND bin(body_mass_g) OVER (PARTITION BY island) AS body_mass_g_bin |> AGGREGATE count(*) AS n GROUP BY island, body_mass_g_bin, sex |> CALL impute(body_mass_g_bin, [sex], n, value => 0, fill_gaps => true, flag => imputed) OVER (PARTITION BY island) |> EXTEND stack(n) OVER (PARTITION BY island, body_mass_g_bin ORDER BY sex DESC NULLS FIRST, n ASC NULLS LAST, imputed ASC NULLS LAST) AS n_stack |> AGGREGATE bar(x => scaled(body_mass_g_bin, title => 'body_mass_g'), y => scaled(n_stack, title => 'count(*)'), color => sex, orient => 'vertical') AS chart GROUP BY island
